BEGIN READ ONLY; SELECT a."Id",a."Status",md5((to_jsonb(a)-'Status'-'UpdatedAt')::text) AS preserved_fields_hash,(SELECT count(*) FROM "AssetEvents" e WHERE e."AssetId"=a."Id") AS history_count,(SELECT count(*) FROM "AssetMaintenances" m WHERE m."AssetId"=a."Id" AND m."Status"='Completed') AS completed_maintenance FROM "Assets" a WHERE a."AssetTag"='SANTA-KABUL-20261025-01'; COMMIT;
